    final r = await runWrapper(tmp.path, mode: 'drop-closed-header');
    expect(r.exitCode, 0, reason: 'stderr: ${r.stderr}');
    expect(r.stderr, contains('healed'));
    final calls = invocations(tmp.path);
    expect(calls, hasLength(2));
